import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"渙","description":"周易集解 - 渙","frontmatter":{"title":"渙","description":"周易集解 - 渙"},"headers":[],"relativePath":"classics/jijie/059.md","filePath":"classics/jijie/059.md"}'),l={name:"classics/jijie/059.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="渙" tabindex="-1">渙 <a class="header-anchor" href="#渙" aria-label="Permalink to “渙”">​</a></h1><h2 id="渙-1" tabindex="-1">渙 <a class="header-anchor" href="#渙-1" aria-label="Permalink to “渙”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>渙，亨。王假有廟，利涉大川，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：說而後散之，故受之以渙。渙者，離也。</p><p>崔憬曰：人說，忘其勞死，而後可散之以徵役，離之以家邦，故曰｢說而後散之，故受之渙。渙者，離也｣。</p><p>虞翻曰：否四之二成坎震，天地交，故亨也。</p><p>虞翻曰：乾為王。假，至也。否體觀。艮為宗廟；乾四之坤二。故王假有廟，王乃在中也。</p><p>虞翻曰：坎為大川。渙，舟檝象。故涉大川。乘木有功，二失正，變應五，故利居貞也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：渙亨，剛來而不窮，柔得位乎外而上同。王假有廟，王乃在中也。利涉大川，乘木有功也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>盧氏曰：此本否卦。乾之九四，來居坤中，剛來成坎，水流而不窮也。坤之六二，上升乾四，柔得位乎外，上承貴王，與上同也。</p><p>荀爽曰：謂陽來居二，在坤之中，為立廟。假，大也。言受命之王，居五大位，上體之中，上享天帝，下立宗廟也。</p><p>虞翻曰：巽為木，坎為水，故乘木有功也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：風行水上，渙。先王以享於帝，立廟。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：謂受命之王，收集散民，上享天帝，下立宗廟也。陰上至四承五，為享帝。陽下至二，為立廟也。離日上為宗廟，而謂天帝宗廟之神所配食者。王者所奉，故繼於上。至於宗廟，其實在地。地者陰中之陽，有似廟中之神。</p><p>虞翻曰：否乾為先王。享，祭也。震為帝、為祭。艮為廟。四之二，殺坤大牲。故以享帝立廟。謂成既濟，有噬嗑食象故也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，用拯馬壯，吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：坎為馬。初失正，動體大壯。得位。故拯馬壯吉，悔亡之矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：初六之吉，順也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：承二，故順也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，渙奔其機，悔亡。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：震為奔，坎為棘，為矯輮。震為足。輮棘有足，艮肱據之，憑機之象也。渙宗廟中，故設機。二失位，變得正，故｢渙奔其機，悔亡｣也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：渙奔其機，得願也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：動而得位，故得願也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，渙其躬，無悔。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>荀爽曰：體中曰躬。謂渙三使承上，為志在外，故無悔。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：渙其躬，志在外也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：渙之為義，內險而外安者也。散躬志外，不固所守，與剛合志。故得無咎。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，渙其群，元吉。渙有丘，匪夷所思。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：謂二已變成坤，坤三爻稱群，得位順五，故元吉也。</p><p>虞翻曰：位半艮山，故稱丘。匪，非也。夷謂震，四應在初，三變坎為思，故匪夷所思也。</p><p>盧氏曰：自二居四，離其群侶，渙其群也，得位承尊，故元吉也。互體有艮，艮為山丘。渙群雖則光大，有丘則非平易，故有匪夷之思也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：渙其群元吉，光大也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂三已變成離，故四光大也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，渙汗其大號。渙王居，無咎。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>《九家易》曰：謂五建二，為諸侯使下君國，故宣佈號令。百姓被澤，若汗之出身，不還反也。此本否卦。體乾為首，來下處二，成坎水，汗之象也；陽稱大，故曰渙汗其大號也。</p><p>荀爽曰：布其德教，王居其所，故無咎矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：王居無咎，正位也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：五為王。艮為居，正位居五，四陰順命。故｢王居無咎，正位也｣。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，渙其血，去逖出，無咎。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：應在三。坎為血，為逖。逖，憂也。二變為觀，坎象不見。故其血去逖出，無咎。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：渙其血，遠害也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：乾為遠，坤為害，體遯上，故遠害也。</p>',72)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
